import {parseCsv,inferMapping,previewImport,applyImport,importFields,onboardingSteps,replacementAreas} from './onboarding-core.mjs';
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const fieldLabels={id:'Matter ID',name:'Client name',email:'Email',phone:'Phone',type:'Practice area',stage:'Stage',owner:'Assigned attorney',language:'Language',incident:'Incident date',summary:'Summary',provider:'Medical provider',insurer:'Insurer'};
const sample='matter_id,client_name,email,phone,practice_area,stage,attorney,language,incident_date,description\r\nML-IMPORT-01,Jamie Example,jamie@example.test,+1 212 555 0148,Vehicle accidents,Intake,Adnan Munawar,English,2026-10-01,"Fictional onboarding record, reviewed before import."\r\nML-IMPORT-02,Noor Example,noor@example.test,+1 212 555 0149,Premises liability,Investigation,Junior attorney,English,2026-10-08,Fictional second matter\r\n';
function download(name,blob){const url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
const post=async(api,path,data)=>{const r=await api(path,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(data)});const d=await r.json();if(!r.ok)throw Error(d.error||'Request failed.');return d;};
export function mountOnboarding(root,ctx){
 let tab='plan',csv='',mapping={},preview=null,baseline='',busy=false;
 const plan=()=>ctx.read().onboarding?.[0]||{id:'firm-plan',firm:'Munawar Law Group',owner:'Adnan Munawar',pilot:'Intake, callbacks and consultation scheduling',team:'Adnan Munawar — supervising attorney\nJunior attorneys — names and access to confirm',checked:[],notes:''};
 const button=(label,action,kind='outline')=>`<button class="button ${kind} small" data-onboard="${action}">${label} ↗</button>`;
 function draw(){const p=plan();root.innerHTML=`<div class="launch-hero"><div><p class="eyebrow">M LAW / MEETING EDITION</p><h2>One firm.<br><em>A connected beginning.</em></h2><p>Thursday, November 12 · 1:00 pm New York time<br>Demonstrate the work. Agree a measured onboarding.</p></div><div class="launch-note"><span class="badge">DEMONSTRATION READY</span><p>Fictional records for today’s walkthrough. Live adoption has separate checks and an explicit partner decision.</p>${button('Start the walkthrough','scenario','light')}</div></div><div class="onboard-tabs" role="tablist">${[['plan','Launch plan'],['import','Import matters'],['readiness','Readiness & backup'],['subscriptions','Software inventory']].map(([k,v])=>`<button role="tab" aria-selected="${tab===k}" data-tab="${k}">${v}</button>`).join('')}</div><div id="onboardPanel">${tab==='plan'?planView(p):tab==='import'?importView():tab==='readiness'?readinessView():subscriptionsView()}</div>`;bind();}
 function planView(p){return `<div class="onboard-grid"><div class="panel"><div class="panel-head"><h2>Firm onboarding</h2><span class="badge gray">${p.checked.length} / ${onboardingSteps.length} planning items</span></div><form id="firmPlan" class="form-stack"><label>Firm<input name="firm" value="${esc(p.firm)}" required maxlength="150"></label><div class="form-grid"><label>Accountable partner<input name="owner" value="${esc(p.owner)}" required maxlength="100"></label><label>First pilot workflow<input name="pilot" value="${esc(p.pilot)}" required maxlength="200"></label></div><label>Team and proposed responsibilities<textarea name="team" rows="3" maxlength="1500">${esc(p.team)}</textarea></label><label>Decisions from the meeting<textarea name="notes" rows="3" maxlength="3000" placeholder="Current tools, export owners, hosting choice and next review…">${esc(p.notes)}</textarea></label><button class="button dark small">Save onboarding plan ↗</button></form><p class="subtle">This roster is a plan. It does not create accounts or invite anyone.</p></div><div class="panel"><h2>Today’s 12-minute walkthrough</h2>${[['reception','01','Meet Maya','Listen, capture a fictional inquiry and reserve a consultation.'],['matters','02','Follow the matter','See the client record, owner and linked tasks.'],['agents','03','Prepare the work','Run a preparation workflow and inspect its draft and review task.'],['approvals','04','Review with an attorney','Track the exact document version and an explicit review decision.'],['knowledge','05','Open the matter graph','Trace the record relationships; discuss the certified law layer.']].map(([view,n,t,d])=>`<button class="walkthrough-step" data-go="${view}"><span>${n}</span><div><strong>${t}</strong><small>${d}</small></div><b>↗</b></button>`).join('')}<p class="subtle">Tailored drafting, telephone calls and court filing are shown only when actually connected.</p></div></div><div class="panel"><h2>Before live adoption</h2><div class="checklist-grid">${onboardingSteps.map(([id,title,detail])=>`<label class="onboard-check"><input type="checkbox" data-check="${id}" ${p.checked.includes(id)?'checked':''}><span><strong>${title}</strong><small>${detail}</small></span></label>`).join('')}</div><p class="subtle">These are self-reported planning notes, separate from the measured connection status.</p>${button('Download meeting brief','brief')}</div>`;}
 function importView(){return `<div class="onboard-grid"><div class="panel"><h2>Bring a sample of your matters</h2><p class="subtle">Start with deidentified or fictional CSV data. Review field mapping and every issue before saving. Existing matter IDs are skipped; records are not overwritten.</p><div class="form-stack"><label>Select CSV<input type="file" id="importFile" accept=".csv,text/csv"></label><div>${button('Use fictional sample','sample')} ${button('Download CSV template','template')}</div><label>CSV preview<textarea id="csvText" rows="7" maxlength="2000000" placeholder="matter_id,client_name,email,…">${esc(csv)}</textarea></label>${button('Map columns','map','dark')}</div><div id="columnMapping">${Object.keys(mapping).length?`<h3>Map the fields</h3><div class="mapping-grid">${importFields.map(field=>`<label>${esc(fieldLabels[field])}${['id','name'].includes(field)?' *':''}<select data-map="${field}"><option value="">Not supplied</option>${parseCsv(csv).headers.map(h=>`<option ${mapping[field]===h?'selected':''}>${esc(h)}</option>`).join('')}</select></label>`).join('')}</div>${button('Validate import','validate','dark')}`:''}</div></div><div class="panel"><h2>Review before import</h2>${preview?`<div class="import-counts"><div><b>${preview.valid}</b> new</div><div><b>${preview.duplicates}</b> skipped</div><div><b>${preview.invalid}</b> invalid</div></div><div class="import-rows">${preview.items.map(r=>`<div class="import-row"><strong>Row ${r.row} · ${esc(r.record.name)}</strong><small>${esc(r.record.id)} · ${esc(r.record.stage)}</small>${r.errors.map(e=>`<p class="issue-error">${esc(e)}</p>`).join('')}${r.warnings.map(e=>`<p class="issue-warning">${esc(e)}</p>`).join('')}</div>`).join('')}</div><label class="check-label"><input id="importConfirm" type="checkbox">I reviewed these rows and am authorized to import this deidentified sample.</label><button id="commitImport" class="button dark small" ${preview.invalid||!preview.valid?'disabled':''}>Import ${preview.valid} reviewed matters ↗</button>`:'<p class="subtle">Validation results, duplicate checks and row errors appear here. No records are saved during preview.</p>'}<h3>Recent imports</h3>${(ctx.read().imports||[]).slice(0,5).map(b=>`<p class="subtle">${b.count} matters · ${esc(b.date.slice(0,10))}<br>${esc(b.status)}</p>`).join('')||'<p class="subtle">No import batches yet.</p>'}</div></div>`;}
 function readinessView(){const s=ctx.status;const checks=[['Shared storage',ctx.mode==='server','Records are shared in the private workspace. This web demonstration keeps its records in your browser.'],['Named staff sign-in',!!s.accountMode,'Admin, attorney, staff and read-only roles; local setup is required.'],['Voice conversations',!!s.voiceConfigured,'Configured endpoint; real calls and native-speaker quality need separate tests.'],['Verification delivery',!!s.verificationConfigured,'A registered contact must receive the code before case access.'],['Drafting assistant',!!s.modelConfigured,'Enable the drafting service before requesting tailored work product.'],['Certified legal ontology',false,'Semantic certification and deadline rule tables remain attorney-led work.'],['Extra sign-in protection & matter restrictions',false,'Required security work before confidential live operations.'],['Telephone forwarding',false,'Existing-number forwarding is intentionally deferred.']];return `<div class="onboard-grid"><div class="panel"><h2>Actual connection status</h2>${checks.map(([title,ok,detail])=>`<div class="readiness-row"><span class="readiness-dot ${ok?'ready':''}"></span><div><strong>${title}</strong><small>${detail}</small></div><span class="badge ${ok?'':'amber'}">${ok?'Configured':'Pending'}</span></div>`).join('')}<p class="subtle">Configured does not mean production-certified. Do not cancel current systems based on this screen.</p></div><div><div class="panel"><h2>Encrypted portable backup</h2><p class="subtle">Includes workspace records and linked files. Encrypted with your passphrase; store it separately. Accounts and deployment secrets are excluded.</p><form id="backupForm" class="form-stack"><label>Backup passphrase<input type="password" name="passphrase" autocomplete="new-password" minlength="16" maxlength="256" required ${ctx.mode!=='server'?'disabled':''}></label><button class="button dark small" ${ctx.mode!=='server'?'disabled':''}>Create encrypted backup ↗</button></form>${ctx.mode!=='server'?'<p class="subtle">Encrypted backups are available in the private firm workspace. Download demonstration records from Workspace settings.</p>':''}</div><div class="panel"><h3>Check a recovery file</h3><form id="inspectBackup" class="form-stack"><label>Backup<input type="file" name="backup" accept=".mlawbackup" required ${ctx.mode!=='server'?'disabled':''}></label><label>Passphrase<input name="passphrase" type="password" minlength="16" required ${ctx.mode!=='server'?'disabled':''}></label><button class="button outline small" ${ctx.mode!=='server'?'disabled':''}>Verify file & counts ↗</button></form><p id="backupResult" class="subtle">Inspection does not change this workspace. Restoration creates a new data directory.</p></div></div></div>`;}
 function subscriptionsView(){const records=ctx.read().subscriptions||[],total=records.filter(r=>r.status!=='Retired').reduce((n,r)=>n+Number(r.monthly),0),retired=records.filter(r=>r.status==='Retired').reduce((n,r)=>n+Number(r.monthly),0);return `<div class="panel"><div class="panel-head"><h2>The software being replaced</h2><span class="badge gray">Inventory · no cancellations are sent</span></div><div class="import-counts"><div><b>$${total.toFixed(0)}</b> recorded monthly spend</div><div><b>$${retired.toFixed(0)}</b> reported retired licences</div></div><form id="subscriptionForm" class="form-grid"><label>Current product<input name="name" required maxlength="100" placeholder="Name from Adnan’s current stack"></label><label>Monthly equivalent cost<input name="monthly" type="number" min="0" max="100000" step="0.01" required></label><label>Owner / export contact<input name="owner" required maxlength="100"></label><label>Category<select name="category">${replacementAreas.map(([n])=>`<option>${n}</option>`).join('')}</select></label><label>Renewal date<input name="renewal" type="date"></label><label>Parallel-run / replacement notes<input name="notes" maxlength="300"></label><button class="button dark small">Add to inventory ↗</button></form><div class="table-wrap"><table><thead><tr><th>PRODUCT</th><th>OWNER</th><th>MONTHLY</th><th>STATE</th></tr></thead><tbody>${records.map(r=>`<tr><td>${esc(r.name)}<small>${esc(r.category)}</small></td><td>${esc(r.owner)}</td><td>$${Number(r.monthly).toFixed(2)}</td><td>${esc(r.status)}</td></tr>`).join('')||'<tr><td colspan="4">Record the current software together at the meeting.</td></tr>'}</tbody></table></div></div><div class="module-grid">${replacementAreas.map(([area,now,next])=>`<article class="module-card"><h3>${area}</h3><p><strong>Built:</strong> ${now}</p><p><strong>Exit checks:</strong> ${next}</p></article>`).join('')}</div><div class="panel"><h3>External services that remain</h3><p class="subtle">Courts, banks, telephone carriers, email delivery and required external portals remain services outside this software. Keep legal research coverage until the firm validates its replacement. Track hosting, model hardware and maintenance separately from retired licences.</p></div>`;}
 async function savePlan(next){const state=ctx.read();state.onboarding=[next];await ctx.write(state,'Onboarding plan updated');}
 function bind(){
  root.querySelectorAll('[data-tab]').forEach(b=>b.onclick=()=>{tab=b.dataset.tab;draw();});root.querySelectorAll('[data-go]').forEach(b=>b.onclick=()=>ctx.go(b.dataset.go));
  root.querySelectorAll('[data-check]').forEach(b=>b.onchange=async()=>{try{const p=plan();p.checked=b.checked?[...new Set([...p.checked,b.dataset.check])]:p.checked.filter(k=>k!==b.dataset.check);await savePlan(p);draw();}catch(e){ctx.toast(e.message);}});
  root.querySelector('#firmPlan')?.addEventListener('submit',async e=>{e.preventDefault();try{await savePlan({...plan(),...Object.fromEntries(new FormData(e.target))});ctx.toast('Onboarding decisions saved.');}catch(err){ctx.toast(err.message);}});
  root.querySelector('#subscriptionForm')?.addEventListener('submit',async e=>{e.preventDefault();try{const d=Object.fromEntries(new FormData(e.target)),s=ctx.read();s.subscriptions??=[];s.subscriptions.push({...d,id:crypto.randomUUID(),monthly:Number(d.monthly),status:'Inventory · not retired'});await ctx.write(s,'Software inventory updated');draw();}catch(err){ctx.toast(err.message);}});
  root.querySelector('#importFile')?.addEventListener('change',async e=>{try{const f=e.target.files[0];if(!f)return;if(f.size>2000000)throw Error('CSV limit is 2 MB.');csv=await f.text();mapping=inferMapping(parseCsv(csv).headers);preview=null;draw();}catch(err){ctx.toast(err.message);}});
  root.querySelector('#csvText')?.addEventListener('input',e=>{csv=e.target.value;preview=null;mapping={};root.querySelector('#columnMapping').innerHTML='';root.querySelector('#commitImport')?.setAttribute('disabled','');});
  root.querySelectorAll('[data-map]').forEach(s=>s.onchange=()=>{mapping[s.dataset.map]=s.value;preview=null;root.querySelector('#commitImport')?.setAttribute('disabled','');});
  root.querySelectorAll('[data-onboard]').forEach(b=>b.onclick=async()=>{if(busy)return;busy=true;b.disabled=true;try{const a=b.dataset.onboard;
   if(a==='sample'){csv=sample;mapping=inferMapping(parseCsv(csv).headers);preview=null;draw();}
   if(a==='template')download('mlaw-import-template.csv',new Blob([sample],{type:'text/csv'}));
   if(a==='map'){mapping=inferMapping(parseCsv(csv).headers);preview=null;draw();}
   if(a==='validate'){preview=ctx.mode==='server'?await post(ctx.api,'/api/onboarding/preview',{csv,mapping}):previewImport(csv,mapping,ctx.read().matters);baseline=JSON.stringify(ctx.read().matters);draw();}
   if(a==='scenario'){const s=ctx.read();if(!s.matters.some(m=>m.id==='ML-MEETING-1112')){s.matters.unshift({id:'ML-MEETING-1112',name:'Taylor Example',type:'Vehicle accidents',stage:'Intake',owner:'Adnan Munawar',language:'English',email:'taylor@example.test',phone:'+1 212 555 0162',incident:'2026-10-25',provider:'Example Medical',insurer:'Example Mutual',summary:'Fictional meeting scenario: a reported rear-end collision. Liability, treatment and coverage remain unverified.',created:'2026-11-12',source:'Meeting demonstration'});s.tasks.unshift({id:crypto.randomUUID(),matter:'ML-MEETING-1112',title:'Review fictional intake and potential conflicts',owner:'Adnan Munawar',date:'2026-11-12',done:false});await ctx.write(s,'Meeting scenario prepared');}ctx.go('reception');ctx.toast('Fictional Taylor Example matter is ready. Start with Maya, then open Case preparation.');}
   if(a==='brief'){const p=plan(),text=`M LAW — MEETING BRIEF\nNovember 12, 2026 · 1:00 pm New York\n\nFirm: ${p.firm}\nPartner: ${p.owner}\nFirst pilot: ${p.pilot}\nTeam: ${p.team}\n\nMeeting decisions\n${p.notes||'To discuss'}\n\nONBOARDING\n${onboardingSteps.map(([id,title])=>(p.checked.includes(id)?'[x] ':'[ ] ')+title).join('\n')}\n\nWorking prototype; fictional/deidentified evaluation. Current systems stay in place until validated parallel-run sign-off. No court filing, retainer, demand, settlement or money movement is performed by this walkthrough.\n`;download('M-Law-meeting-brief.txt',new Blob([text],{type:'text/plain'}));}
  }catch(e){ctx.toast(e.message);}finally{busy=false;b.disabled=false;}});
  root.querySelector('#commitImport')?.addEventListener('click',async()=>{if(busy)return;if(!root.querySelector('#importConfirm').checked){ctx.toast('Review the rows and check the import confirmation.');return;}busy=true;try{if(!preview)throw Error('Validate the current CSV first.');if(ctx.mode==='server'){await post(ctx.api,'/api/onboarding/import',{token:preview.token,confirm:'IMPORT'});await ctx.refresh();}else{if(baseline!==JSON.stringify(ctx.read().matters))throw Error('Workspace changed. Preview again.');const s=applyImport(ctx.read(),preview,crypto.randomUUID());await ctx.write(s,'Reviewed CSV imported');}preview=null;draw();ctx.toast('Matters imported with linked verification tasks.');}catch(e){ctx.toast(e.message);}finally{busy=false;}});
  root.querySelector('#backupForm')?.addEventListener('submit',async e=>{e.preventDefault();const b=e.target.querySelector('button');b.disabled=true;try{const passphrase=new FormData(e.target).get('passphrase');const r=await ctx.api('/api/backup/create',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({passphrase})});if(!r.ok)throw Error((await r.json()).error);download('mlaw-workspace.mlawbackup',await r.blob());e.target.reset();ctx.toast('Encrypted backup downloaded. Keep its passphrase separate.');}catch(err){ctx.toast(err.message);}finally{b.disabled=false;}});
  root.querySelector('#inspectBackup')?.addEventListener('submit',async e=>{e.preventDefault();const b=e.target.querySelector('button');b.disabled=true;try{const f=new FormData(e.target),file=f.get('backup');if(file.size>50*1024*1024+68)throw Error('Backup exceeds 50 MB.');const data=await new Promise((resolve,reject)=>{const r=new FileReader();r.onload=()=>resolve(r.result.split(',')[1]);r.onerror=reject;r.readAsDataURL(file);});const r=await post(ctx.api,'/api/backup/inspect',{passphrase:f.get('passphrase'),data});root.querySelector('#backupResult').textContent=`Verified: ${r.matters} matters, ${r.documents} documents, ${r.tasks} tasks and ${r.files} files. File checksums match. No records were restored or changed.`;e.target.reset();}catch(err){ctx.toast(err.message);}finally{b.disabled=false;}});
 }
 draw();
}
export function mountApprovals(root,ctx){
 const gates=['Case acceptance','Demand review','Court paper review','Closing / disbursement review'];
 async function fingerprint(doc){return [...new Uint8Array(await crypto.subtle.digest('SHA-256',new TextEncoder().encode(JSON.stringify({id:doc.id,matter:doc.matter,text:doc.text,name:doc.name}))))].map(b=>b.toString(16).padStart(2,'0')).join('');}
 function draw(){const s=ctx.read();root.innerHTML=`<div class="panel"><h2>Request review of a specific document</h2><p class="subtle">A decision is bound to the document’s recorded content version. An edited document needs a fresh review. These are internal review records; they do not send a retainer or demand, file papers, approve a client settlement or release funds.</p><form id="requestReview" class="form-grid"><label>Review gate<select name="gate">${gates.map(g=>`<option>${g}</option>`).join('')}</select></label><label>Work product<select name="documentId" required>${s.documents.map(d=>`<option value="${esc(d.id)}">${esc(d.name)}</option>`).join('')}</select></label><button class="button dark small" ${s.documents.length?'':'disabled'}>Request attorney review ↗</button></form></div><div class="review-grid">${(s.approvals||[]).map(a=>`<article class="panel"><p class="eyebrow">${esc(a.gate)}</p><h3>${esc(a.title)}</h3><span class="badge ${a.status==='Pending review'?'amber':''}">${esc(a.status)}</span><p class="subtle">Matter ${esc(a.matter)} · requested by ${esc(a.requestedBy)}<br>Document version recorded for review</p>${a.status==='Pending review'?`<button class="button outline small" data-review="${a.id}">Open exact work product ↗</button>`:`<p class="subtle">${esc(a.reviewer)} · ${esc(a.identity)}<br>${esc(a.externalAction)}</p>`}</article>`).join('')||'<div class="panel"><h3>Ready for the team’s decisions</h3><p class="subtle">Prepare a document in Case preparation or Documents & files, then request its review here.</p></div>'}</div>`;
 root.querySelector('#requestReview').onsubmit=async e=>{e.preventDefault();try{const data=Object.fromEntries(new FormData(e.target));if(ctx.mode==='server'){await post(ctx.api,'/api/approvals/request',data);await ctx.refresh();}else{const s=ctx.read(),d=s.documents.find(d=>d.id===data.documentId),documentHash=await fingerprint(d);s.approvals??=[];if(s.approvals.some(a=>a.documentId===d.id&&a.documentHash===documentHash&&a.status==='Pending review'))throw Error('This document version is already waiting for review.');s.approvals.unshift({...data,id:crypto.randomUUID(),documentHash,matter:d.matter,title:d.name,status:'Pending review',requestedBy:'Demo reviewer',date:new Date().toISOString()});await ctx.write(s,'Document review requested');}draw();ctx.toast('Exact document version added to the review queue.');}catch(err){ctx.toast(err.message);}};
 root.querySelectorAll('[data-review]').forEach(b=>b.onclick=()=>{const a=ctx.read().approvals.find(a=>a.id===b.dataset.review),doc=ctx.read().documents.find(d=>d.id===a.documentId);ctx.modal('INTERNAL REVIEW / '+a.gate,`<h2>${esc(a.title)}</h2><pre class="draft">${esc(doc?.text||'Document unavailable.')}</pre><p class="subtle">Review acknowledges this internal work product only. ${ctx.mode==='browser'?'This browser preview uses a simulated reviewer identity.':'Private workspace decisions record the signed-in staff identity when individual accounts are enabled.'}</p><form id="decisionForm" class="form-stack"><label>Decision<select name="decision"><option value="approve">Acknowledge internal review</option><option value="return">Return for revision</option></select></label><label>Type APPROVE or RETURN to match your decision<input name="confirmation" required autocomplete="off"></label><button class="button dark small">Record decision ↗</button></form>`);document.querySelector('#decisionForm').onsubmit=async e=>{e.preventDefault();try{const d=Object.fromEntries(new FormData(e.target));if(ctx.mode==='server'){await post(ctx.api,'/api/approvals/decide',{id:a.id,...d});await ctx.refresh();}else{if(d.confirmation!==(d.decision==='approve'?'APPROVE':'RETURN'))throw Error('Type the matching explicit confirmation.');if(!doc||await fingerprint(doc)!==a.documentHash)throw Error('Document changed. Request a new review.');a.status=d.decision==='approve'?'Internal review acknowledged':'Returned for revision';a.reviewer='Demo reviewer';a.identity='Simulated browser identity';a.reviewedAt=new Date().toISOString();a.externalAction='None — no external action executed';await ctx.write(ctx.read(),'Internal document review recorded');}document.querySelector('#modal').close();draw();ctx.toast('Review recorded. No external action was executed.');}catch(err){ctx.toast(err.message);}};});
 }draw();
}
